"""Pure task dependency planning."""

def plan_batches(tasks: list[dict], completed: list[str]) -> list[list[str]]:
    def is_id(value):
        return type(value) is str and value != ""

    if type(tasks) is not list or type(completed) is not list:
        raise ValueError("INVALID_TASK")
    for task in tasks:
        if type(task) is not dict or set(task) != {"id", "depends_on", "priority"}:
            raise ValueError("INVALID_TASK")
        if not is_id(task["id"]) or type(task["priority"]) is not int:
            raise ValueError("INVALID_TASK")
        deps = task["depends_on"]
        if type(deps) is not list or not all(is_id(dep) for dep in deps):
            raise ValueError("INVALID_TASK")
    if not all(is_id(entry) for entry in completed):
        raise ValueError("INVALID_TASK")

    ids = [task["id"] for task in tasks]
    known = set(ids)
    if len(known) != len(ids):
        raise ValueError("DUPLICATE_TASK")

    done = set(completed)
    for task in tasks:
        for dep in task["depends_on"]:
            if dep not in known and dep not in done:
                raise ValueError("MISSING_DEPENDENCY")

    remaining = [
        (index, task) for index, task in enumerate(tasks) if task["id"] not in done
    ]
    pending = {}
    dependents = {}
    for index, task in remaining:
        waiting = {dep for dep in task["depends_on"] if dep not in done}
        pending[task["id"]] = len(waiting)
        for dep in waiting:
            dependents.setdefault(dep, []).append(index)

    ready = [index for index, task in remaining if pending[task["id"]] == 0]
    batches = []
    emitted = 0
    while ready:
        ready.sort(key=lambda index: (-tasks[index]["priority"], index))
        batches.append([tasks[index]["id"] for index in ready])
        emitted += len(ready)
        next_ready = []
        for index in ready:
            for child in dependents.get(tasks[index]["id"], ()):
                child_id = tasks[child]["id"]
                pending[child_id] -= 1
                if pending[child_id] == 0:
                    next_ready.append(child)
        ready = next_ready

    if emitted != len(remaining):
        raise ValueError("DEPENDENCY_CYCLE")
    return batches
